public class Compiler_toSource_TriageGen2Test {

  private Compiler compiler;
  private CompilerOptions options;
  private CodeBuilder cb;
  private Node root;

  @Before
  public void setUp() {
    compiler = spy(new Compiler());
    options = new CompilerOptions();
    compiler.initOptions(options);
    cb = new CodeBuilder();
    root = mock(Node.class);
  }

  @Test
  public void testToSource_NoOptions() {
    // Mock toSource(root, sourceMap, isFirst) call inside the Callable
    // Note: Since toSource is a method of the same class, we spy it or mock the underlying logic.
    // However, the provided code snippet shows the logic is embedded in the lambda.
    // We simulate the node behavior.
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getJSDocInfo()).thenReturn(null);

    // We need to mock the internal call to toSource(root, sourceMap, boolean)
    // Because the method is called on 'this', we use doReturn on the spy.
    doReturn("var x = 1").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    compiler.toSource(cb, 0, root);

    assertEquals("var x = 1;", cb.toString());
  }

  @Test
  public void testToSource_WithDelimiter() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "File: %name% (Num: %num%)";

    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getSourceFileName()).thenReturn("test.js");
    when(root.getJSDocInfo()).thenReturn(null);
    doReturn("var x = 1").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    // First call: empty cb
    compiler.toSource(cb, 5, root);

    // Check delimiter format: "File: test.js (Num: 5)\nvar x = 1;"
    String expected = "File: test.js (Num: 5)\nvar x = 1;";
    assertEquals(expected, cb.toString());
  }

  @Test
  public void testToSource_WithDelimiterAndNewlineHeuristic() {
    options.printInputDelimiter = true;
    options.inputDelimiter = "---%name%---";

    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getSourceFileName()).thenReturn("test.js");
    when(root.getJSDocInfo()).thenReturn(null);
    doReturn("var x = 1").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    // Pre-fill cb to trigger the \n append logic
    cb.append("existing");

    compiler.toSource(cb, 1, root);

    // Should append \n because existing doesn't end with \n
    assertTrue(cb.toString().contains("existing\n---test.js---"));
  }

  @Test
  public void testToSource_WithLicense() {
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getJSDocInfo()).thenReturn(mock(JSDocInfo.class));
    when(root.getJSDocInfo().getLicense()).thenReturn("MIT License");
    doReturn("code").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    compiler.toSource(cb, 0, root);

    String expected = "/*\nMIT License*/\ncode;";
    assertEquals(expected, cb.toString());
  }

  @Test
  public void testToSource_SourceMapOffset() {
    options.sourceMapOutputPath = "out.map";
    SourceMap mockMap = mock(SourceMap.class);
    // We need to inject the sourceMap into the compiler. 
    // In real Compiler, sourceMap is a field. We assume it's accessible or set via internal state.
    // For testing purposes, we assume the compiler has a sourceMap object.

    when(root.getType()).thenReturn(Token.SCRIPT);
    doReturn("code").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    compiler.toSource(cb, 0, root);
    // If the code runs, it calls sourceMap.setStartingPosition.
  }

  @Test
  public void testToSource_NoSemicolonNeeded() {
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getJSDocInfo()).thenReturn(null);
    // Case 1: ends with ;
    doReturn("var x = 1;").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());
    compiler.toSource(cb, 0, root);
    assertEquals("var x = 1;", cb.toString());

    cb = new CodeBuilder();

    // Case 2: ends with \n and preceding is ;
    doReturn("var x = 1;\n").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());
    compiler.toSource(cb, 0, root);
    assertEquals("var x = 1;\n", cb.toString());
  }

  @Test(expected = RuntimeException.class)
  public void testToSource_ThrowsOnInvalidType() {
    // Preconditions.checkState(root.getType() == Token.SCRIPT)
    when(root.getType()).thenReturn(Token.VAR);
    options.printInputDelimiter = true;

    compiler.toSource(cb, 0, root);
  }

  @Test(expected = RuntimeException.class)
  public void testToSource_ThrowsOnNullSourceName() {
    options.printInputDelimiter = true;
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getSourceFileName()).thenReturn(null);

    compiler.toSource(cb, 0, root);
  }

  @Test(expected = RuntimeException.class)
  public void testToSource_ThrowsOnEmptySourceName() {
    options.printInputDelimiter = true;
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getSourceFileName()).thenReturn("");

    compiler.toSource(cb, 0, root);
  }

  @Test
  public void testToSource_EmptyCodeAppend() {
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getJSDocInfo()).thenReturn(null);
    doReturn("").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    compiler.toSource(cb, 0, root);
    assertEquals("", cb.toString());
  }

  @Test
  public void testToSource_SingleCharCode() {
    when(root.getType()).thenReturn(Token.SCRIPT);
    when(root.getJSDocInfo()).thenReturn(null);
    doReturn("a").when(compiler).toSource(any(Node.class), any(SourceMap.class), anyBoolean());

    compiler.toSource(cb, 0, root);
    // length 1, lastChar 'a', secondLastChar '\0'. No semicolon.
    assertEquals("a;", cb.toString());
  }
}

// Helper to allow compiler.toSource(Node, SourceMap, boolean) to be mocked
// In a real environment, this method is private/protected and is part of the class.
// Since we are testing the public method that calls it, the spy is necessary.
